@startuml

class Museum {
  + name : string
}

class Location {
  + name : string
}

class Exhibition {
  + name : string
  + openingDate : date
}

class ExhibitionItem {
  + description : string
}

class Piece {
  + description : string
}

class Collector {
  + name : string
}

class Employee {
  + name : string
}

Museum "1" *-- "* Location"
Location "1" -- "* Exhibition"
Exhibition "1" -- "1" Employee : coordinator
Exhibition "1" *-- "* ExhibitionItem"
ExhibitionItem "1" -- "1..*" Piece : sourced from
ExhibitionItem "1" -- "1..*" Collector : requested from
Employee "0..1" -- "0..*" Employee : coach

@enduml

